/* Diferenciator 1.3.29 - safe GeoJSON classroom map utilities. */
const finite=n=>Number.isFinite(Number(n));
const point=p=>Array.isArray(p)&&p.length>=2&&finite(p[0])&&finite(p[1]);
function sqDist(a,b){const dx=a[0]-b[0],dy=a[1]-b[1];return dx*dx+dy*dy}
function sqSegDist(p,a,b){let x=a[0],y=a[1],dx=b[0]-x,dy=b[1]-y;if(dx||dy){const t=((p[0]-x)*dx+(p[1]-y)*dy)/(dx*dx+dy*dy);if(t>1){x=b[0];y=b[1]}else if(t>0){x+=dx*t;y+=dy*t}}dx=p[0]-x;dy=p[1]-y;return dx*dx+dy*dy}
function simplifyRadial(points,sqTol){let prev=points[0],out=[prev];for(let i=1;i<points.length;i++){const p=points[i];if(sqDist(p,prev)>sqTol){out.push(p);prev=p}}if(prev!==points[points.length-1])out.push(points[points.length-1]);return out}
function simplifyDP(points,sqTol){const last=points.length-1,markers=new Uint8Array(points.length);markers[0]=markers[last]=1;const stack=[[0,last]];while(stack.length){const [first,end]=stack.pop();let max=sqTol,index=0;for(let i=first+1;i<end;i++){const d=sqSegDist(points[i],points[first],points[end]);if(d>max){index=i;max=d}}if(max>sqTol){markers[index]=1;stack.push([first,index],[index,end])}}return points.filter((_,i)=>markers[i])}
export function simplifyLine(points,tolerance=.001){const src=(Array.isArray(points)?points:[]).filter(point).map(p=>[Number(p[0]),Number(p[1])]);if(src.length<=2)return src;const sq=Math.max(0,Number(tolerance)||0)**2;return simplifyDP(simplifyRadial(src,sq),sq)}
function ringsFromGeometry(g){if(!g||!g.type)return [];if(g.type==='Polygon')return (g.coordinates||[]).map(r=>({ring:r,hole:false}));if(g.type==='MultiPolygon')return (g.coordinates||[]).flatMap(poly=>(poly||[]).map((r,i)=>({ring:r,hole:i>0})));return []}
function cleanFeature(f,index,tol,maxPoints){if(!f||f.type!=='Feature')return null;const type=f.geometry&&f.geometry.type;if(type!=='Polygon'&&type!=='MultiPolygon')return null;let used=0;const cleanRing=r=>{const s=simplifyLine(r,tol);used+=s.length;return used>maxPoints?[]:s};let coordinates;if(type==='Polygon')coordinates=(f.geometry.coordinates||[]).map(cleanRing).filter(r=>r.length>=4);else coordinates=(f.geometry.coordinates||[]).map(poly=>(poly||[]).map(cleanRing).filter(r=>r.length>=4)).filter(Boolean);if(!coordinates.length)return null;const p=f.properties||{};const id=String(f.id??p.id??p.code??p.kod??p.nationalCode??index).slice(0,100);const name=String(p.name??p.NAME??p.nazev??p.NAZEV??p.NAZ_CZNUTS3??id).slice(0,160);return {type:'Feature',id,properties:{id,name},geometry:{type,coordinates}}}
export function normalizeGeoJson(input,{tolerance=.001,maxFeatures=250,maxPoints=45000}={}){let data=input;if(typeof data==='string'){if(data.length>8_000_000)throw Error('GeoJSON je příliš velký.');data=JSON.parse(data)}if(!data||data.type!=='FeatureCollection'||!Array.isArray(data.features))throw Error('Je vyžadován GeoJSON FeatureCollection.');const features=[];let points=0;for(let i=0;i<data.features.length&&features.length<maxFeatures;i++){const f=cleanFeature(data.features[i],i,tolerance,maxPoints-points);if(!f)continue;for(const r of ringsFromGeometry(f.geometry))points+=r.ring.length;if(points>maxPoints)break;features.push(f)}if(!features.length)throw Error('GeoJSON neobsahuje podporované Polygon/MultiPolygon prvky.');return {type:'FeatureCollection',features,meta:{source:String(data.name||data.title||''),featureCount:features.length,pointCount:points}}}
export function geoJsonBounds(fc){let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;for(const f of fc.features||[])for(const {ring} of ringsFromGeometry(f.geometry))for(const p of ring||[]){if(!point(p))continue;minX=Math.min(minX,+p[0]);maxX=Math.max(maxX,+p[0]);minY=Math.min(minY,+p[1]);maxY=Math.max(maxY,+p[1])}if(!Number.isFinite(minX+minY+maxX+maxY)||minX===maxX||minY===maxY)throw Error('GeoJSON nemá použitelný souřadnicový rozsah.');return [minX,minY,maxX,maxY]}
export function geoJsonFeatureSummary(fc){return (fc.features||[]).slice(0,250).map((f,i)=>({id:String(f.id??f.properties?.id??i),name:String(f.properties?.name??f.id??i)}))}
